export function publicPricingGame(game){if(!game)return null;return Object.fromEntries(Object.entries(game).filter(([k])=>!k.startsWith("_")));}

export function syncClockGame(game,now=Date.now()){
  if(game?.type!=="clockGame"||game.status!=="playing"||!game.clockEndsAt)return false;
  game.secondsLeft=Math.max(0,Math.ceil((game.clockEndsAt-now)/1000));
  if(game.secondsLeft)return false;
  game.timeoutPrice=game._prices[game.itemIndex];
  finish(game,false,"Time is up!");
  return true;
}

export function revealDeferredPrice(game) {
  if (!game?._pendingPriceReveal || !game.priceReveal) throw new Error("No price is waiting to be revealed");
  const pending=game._pendingPriceReveal;
  game.priceReveal.actual=pending.actual;
  game.priceReveal.correct=pending.outcome?.kind === "success" || pending.outcome?.kind === "win";
  if (pending.outcome) outcome(game,pending.outcome.kind,pending.outcome.text);
  return game;
}

export function clearDeferredPrice(game) {
  if (!game?._pendingPriceReveal) throw new Error("No revealed price is waiting");
  game.priceReveal=null;
  game._pendingPriceReveal=null;
  return game;
}

export function initialPrizeAnnouncements(game) {
  if (!game) return [];
  if (game.type === "plinko" || game.type === "punchABunch") return [game.qualifiers[0]];
  if (game.type === "shellGame") return [game.bonusPrize, game.items[0]];
  if (game.type === "cliffHangers" || game.type === "clockGame") return [game.items[0]];
  return game.introPrizes || [];
}

export function settlePricingAnimation(game) {
  if(game?.type==="cliffHangers"){
    if(game.stage!=="climbing"||!game._pendingCliffReveal)throw new Error("The climber is not moving");const p=game._pendingCliffReveal;game.history.push(`${game.items[p.i].name}: ${money(p.guess)}, actual ${money(p.actual)} — ${p.error} steps.`);outcome(game,p.error===0?"success":"failure",p.error===0?"Exactly right!":`${p.error} climber step${p.error===1?"":"s"}.`);const revealOutcome=game.lastOutcome;game.itemIndex+=1;game.stage="pricing";game.mode="number";if(game.climber>25){game.cliffOver=true;finish(game,false,"The climber went over the cliff!");}else if(game.itemIndex===3){game.cliffFinalWin=true;finish(game,true,`HE MADE IT! You won all three prizes!`,game._prices.reduce((sum,price)=>sum+price,0));}else{game.prompt=`What is the price of the ${game.items[game.itemIndex].name}?`;introduceNext(game,game.items[game.itemIndex]);}holdPriceReveal(game,p.beforeSeq,p.beforeOutcome,game.items[p.i],money(p.guess),p.actual,revealOutcome);game._pendingCliffReveal=null;return game;
  }
  if (game?.type !== "plinko" || game.stage !== "dropping" || !game.lastDrop) throw new Error("No pricing-game animation is active");
  const won=game.slots[game.lastDrop.landing];game.lastDrop.value=won;game.winnings+=won;game.chipsLeft-=1;game.history.push(`Chip landed in ${money(won)}.`);game.stage="drop";game.mode="drop";outcome(game,won?"success":"failure",`The chip landed on ${money(won)}.`);
  if(!game.chipsLeft)finish(game,game.winnings>0,`You won ${money(game.winnings)} on Plinko!`);else game.prompt=`Tap a drop position for your next chip. ${game.chipsLeft} remaining.`;
  return game;
}
